// assets/js/common.js - votes and Sign in with X now run on Cloudflare (Pages Functions + D1).

// ====================== VIDEO POSTERS ======================
// iOS Safari does not paint a first frame for preload="metadata" videos, so
// every <video> gets a poster image. Use the entry's "poster" field when set;
// for local videos under /assets/ fall back to "<same path>-poster.webp"
// (generated by scripts/generate-video-posters.py).
const VIDEO_EXT_RE = /\.(mp4|webm|mov)$/i;

window.isVideoUrl = function(url) {
  if (!url) return false;
  return VIDEO_EXT_RE.test(String(url).split(/[?#]/)[0]);
};

// Percent-encode a URL/path once (spaces, quotes, etc.) without double-encoding.
// Relative paths are made root-relative so they work from any page depth.
function safeUrl(url) {
  let decoded = String(url).trim();
  if (!/^([a-z][a-z0-9+.-]*:|\/)/i.test(decoded)) decoded = '/' + decoded;
  try { decoded = decodeURI(decoded); } catch (e) { /* keep as-is */ }
  return encodeURI(decoded).replace(/'/g, '%27');
}

window.getVideoPoster = function(src, explicitPoster) {
  if (explicitPoster) return safeUrl(explicitPoster);
  if (!src) return '';
  const path = String(src).split(/[?#]/)[0];
  if (!VIDEO_EXT_RE.test(path)) return '';
  let local = null;
  if (/^\/?assets\//i.test(path)) local = path;
  else {
    try {
      const u = new URL(path, window.location.href);
      if (u.origin === window.location.origin && /^\/assets\//i.test(u.pathname)) local = u.pathname;
    } catch (e) { /* not a URL */ }
  }
  if (!local) return '';
  return safeUrl(local.replace(VIDEO_EXT_RE, '-poster.webp'));
};

// Returns ' poster="..."' (or '') for use inside a <video> template string.
window.videoPosterAttr = function(src, explicitPoster) {
  const poster = window.getVideoPoster(src, explicitPoster);
  return poster ? ` poster="${poster}"` : '';
};

// ====================== USERS + BACKGROUND ======================
let allUsers = null;

async function loadUsers() {
  if (allUsers) return allUsers;
  try {
    const res = await fetch('/data/users.json');
    allUsers = await res.json();
  } catch (e) {
    allUsers = {};
  }
  return allUsers;
}

function getUserData(username) {
  if (!username || !allUsers) return {};
  const clean = username.replace('@', '').trim();
  return allUsers[clean] || {};
}

function getLocalAvatar(post) {
  let username = post.username || post.user || post.avatar || post.author || '';
  if (!username) return '/assets/images/users/@unknown.webp';
  const clean = username.replace('@', '').trim();
  return `/assets/images/users/@${clean}.webp`;
}
const bgs = [
  'assets/images/backgrounds/bg1.webp','assets/images/backgrounds/bg2.webp',
  'assets/images/backgrounds/bg3.webp','assets/images/backgrounds/bg4.webp',
  'assets/images/backgrounds/bg5.webp','assets/images/backgrounds/bg6.webp',
  'assets/images/backgrounds/bg7.webp','assets/images/backgrounds/bg8.webp',
  'assets/images/backgrounds/bg9.webp','assets/images/backgrounds/bg10.webp',
  'assets/images/backgrounds/bg11.webp','assets/images/backgrounds/bg12.webp',
  'assets/images/backgrounds/bg13.webp','assets/images/backgrounds/bg14.webp',
  'assets/images/backgrounds/bg15.webp','assets/images/backgrounds/bg16.webp',
  'assets/images/backgrounds/bg17.webp','assets/images/backgrounds/bg18.webp',
  'assets/images/backgrounds/bg19.webp','assets/images/backgrounds/bg20.webp'
];

function setRandomBackground() {
  const randomBg = bgs[Math.floor(Math.random() * bgs.length)];
  document.body.style.backgroundImage = `url('/${randomBg}')`;
  document.body.style.backgroundPosition = '50% 35%';
  document.body.style.backgroundSize = 'cover';
  document.body.style.backgroundRepeat = 'no-repeat';
  document.body.style.backgroundAttachment = 'fixed';
}

// ====================== LAYOUT (partials) ======================
async function loadLayout() {
  try {
    const headerRes = await fetch('/assets/partials/header.html');
    const headerHTML = await headerRes.text();
    document.body.insertAdjacentHTML('afterbegin', headerHTML);

    const footerRes = await fetch('/assets/partials/footer.html');
    const footerHTML = await footerRes.text();
    document.body.insertAdjacentHTML('beforeend', footerHTML);

    highlightActiveNav();
    initSupportLink();
    console.log('✅ Header + Footer loaded');
  } catch (e) {
    console.error('Layout load failed:', e);
  }
}

// Footer "Support this project" link: hidden until a real https URL is set
// in data-kofi-url (assets/partials/footer.html).
function initSupportLink() {
  document.querySelectorAll('.footer__support-link[data-kofi-url]').forEach(link => {
    const url = (link.getAttribute('data-kofi-url') || '').trim();
    if (!/^https:\/\//i.test(url)) return;
    link.href = url;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.hidden = false;
  });
}

function highlightActiveNav() {
  const navLinks = document.querySelectorAll('.nav-link');
  if (navLinks.length === 0) return;
  const currentPage = document.body.getAttribute('data-page') || '';
  navLinks.forEach(link => {
    link.classList.remove('active');
    const href = link.getAttribute('href').replace('.html', '').toLowerCase();
    if (href === currentPage.toLowerCase()) link.classList.add('active');
  });
}

// ====================== TOAST ======================
window.showToast = function(message) {
  const toast = document.getElementById('toast');
  if (!toast) return;
  const text = document.getElementById('toast-text');
  text.textContent = message;
  toast.classList.remove('hidden');
  toast.style.transform = 'translate(-50%, 0)';
  setTimeout(() => {
    toast.style.transform = 'translate(-50%, 80px)';
    setTimeout(() => toast.classList.add('hidden'), 400);
  }, 2800);
};

window.checkDeepLink = function() {
  const hash = window.location.hash.replace('#', '').trim();
  if (!hash || isNaN(hash)) return;
  const id = parseInt(hash);

  if (window.allMemes && window.allMemes[id]) openMemeModal(id);
  else if (window.allBattles && window.allBattles[id]) openBattleModal(id);
  else if (window.allCategories && window.allCategories[id]) openCategoryModal(id);
};

// ====================== DEEP LINK (ROBUST RETRY VERSION) ======================
window.initPage = async function(pageType) {
  await loadUsers();

  if (pageType === 'memes') {
    const res = await fetch('/data/memes.json');
    window.allMemes = await res.json();
    if (typeof renderMemeGrid === 'function') renderMemeGrid();
  } 
  else if (pageType === 'battles') {
    const res = await fetch('/data/battles.json');
    window.allBattles = await res.json();
    if (typeof renderBattleGrid === 'function') renderBattleGrid();
  } 
  else if (pageType === 'categories') {
    const res = await fetch('/data/categories.json');
    window.allCategories = await res.json();
    if (typeof renderCategoryGrid === 'function') renderCategoryGrid();
  }

  // Safe deep link (no retry loop that can break anything)
  console.log('🚀 initPage complete for', pageType);
  setTimeout(() => {
    if (typeof window.checkDeepLink === 'function') window.checkDeepLink();
  }, 150);
};

// ====================== AUTH (Sign in with X) ======================
window.currentUser = null;
let authReady = null;

function loadAuth() {
  if (!authReady) {
    authReady = fetch('/api/me', { credentials: 'same-origin', cache: 'no-store' })
      .then(r => r.ok ? r.json() : { user: null })
      .catch(() => ({ user: null }))
      .then(d => { window.currentUser = d.user || null; renderAuthUI(); return window.currentUser; });
  }
  return authReady;
}

const X_LOGO_SVG = '<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" fill="currentColor"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>';

function escapeHtml(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

window.signIn = function(event) {
  if (event) { event.preventDefault(); event.stopPropagation(); }
  const back = location.pathname + location.search + location.hash;
  location.href = '/auth/login?return=' + encodeURIComponent(back);
};

window.signOut = async function(event) {
  if (event) event.preventDefault();
  try { await fetch('/auth/logout', { method: 'POST', credentials: 'same-origin' }); } catch (e) { /* ignore */ }
  window.currentUser = null;
  votesState.mine = {};
  renderAuthUI();
  refreshAllVoteUIs();
  window.showToast('Signed out.');
};

function renderAuthUI() {
  const slot = document.getElementById('auth-slot');
  if (!slot) return;
  const u = window.currentUser;
  if (u) {
    const avatar = /^https:\/\//.test(u.avatar || '') ? u.avatar : '';
    slot.innerHTML =
      `<span class="auth-user" title="Signed in with X">` +
      (avatar ? `<img class="auth-user__avatar" src="${escapeHtml(avatar)}" alt="" referrerpolicy="no-referrer">` : '') +
      `<span class="auth-user__x" aria-hidden="true">${X_LOGO_SVG}</span>` +
      `<a class="auth-user__handle" href="https://x.com/${encodeURIComponent(u.handle)}" target="_blank" rel="noopener noreferrer">@${escapeHtml(u.handle)}</a>` +
      `<button type="button" class="auth-user__out" onclick="signOut(event)">Sign out</button></span>`;
  } else {
    slot.innerHTML = `<button type="button" class="auth-btn" onclick="signIn(event)">${X_LOGO_SVG}<span>Sign in with X</span></button>`;
  }
}

// Message after returning from /auth/callback (?login=ok|cancelled|error|expired).
function handleLoginReturn() {
  const url = new URL(location.href);
  const flag = url.searchParams.get('login');
  if (!flag) return;
  url.searchParams.delete('login');
  history.replaceState(null, '', url.pathname + (url.search || '') + url.hash);
  const msg = {
    ok: null,
    cancelled: 'Sign in cancelled.',
    expired: 'Sign in took too long. Please try again.',
    error: 'Sign in with X failed. Please try again.'
  }[flag];
  if (msg) setTimeout(() => window.showToast(msg), 400);
  else if (window.currentUser) setTimeout(() => window.showToast('Signed in as @' + window.currentUser.handle + ' ✅'), 400);
}

// ====================== BATTLES VOTING SYSTEM ======================
// Totals = anonymous legacy votes (imported from Firebase) + signed-in votes.
// One vote per X account per battle (enforced by the database); you may change it.
const votesState = { totals: {}, mine: {}, loaded: false };

async function loadVotes() {
  try {
    const res = await fetch('/api/votes', { credentials: 'same-origin', cache: 'no-store' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const d = await res.json();
    votesState.totals = d.totals || {};
    votesState.mine = d.mine || {};
    votesState.loaded = true;
  } catch (e) {
    console.warn('Could not load votes', e);
  }
}

function applyVoteUI(grokBtn, humanBtn, id) {
  if (!grokBtn || !humanBtn) return;
  const t = votesState.totals[id] || { grok: 0, human: 0 };
  const mine = votesState.mine[id];
  if ((t.grok + t.human) > 0) {
    grokBtn.innerHTML = `Grok <span class="vote-count">${t.grok}</span>`;
    humanBtn.innerHTML = `<span class="vote-count">${t.human}</span> Human`;
  } else {
    grokBtn.textContent = 'Grok Won';
    humanBtn.textContent = 'Human Won';
  }
  grokBtn.classList.toggle('vote-mine', mine === 'grok');
  humanBtn.classList.toggle('vote-mine', mine === 'human');
  grokBtn.disabled = false;
  humanBtn.disabled = false;
}

function updateGridVoteUI(id) {
  applyVoteUI(document.getElementById(`grok-btn-${id}`), document.getElementById(`human-btn-${id}`), String(id));
}

window.updateModalVoteUI = function() {
  if (!window.currentBattleId) return;
  applyVoteUI(document.getElementById('modal-grok-btn'), document.getElementById('modal-human-btn'), String(window.currentBattleId));
};

function refreshAllVoteUIs() {
  Object.keys(window.allBattles || {}).forEach(id => updateGridVoteUI(id));
  window.updateModalVoteUI();
}

function updateAllBattleVoteUIs() {
  Promise.all([loadAuth(), loadVotes()]).then(refreshAllVoteUIs);
}

window.vote = async function(event, winner, id) {
  event.stopImmediatePropagation();
  event.preventDefault();
  if (winner !== 'grok' && winner !== 'human') return;
  id = String(id);

  await loadAuth();
  if (!window.currentUser) {
    window.showToast('Sign in with X to vote 🗳️');
    setTimeout(() => window.signIn(), 900);
    return;
  }
  if (votesState.mine[id] === winner) {
    window.showToast(`You already voted ${winner.toUpperCase()} on this battle 🏆`);
    return;
  }

  setVoteButtonsDisabled(id, true);
  try {
    const res = await fetch('/api/vote', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id, choice: winner })
    });
    if (res.status === 401) {
      window.currentUser = null; renderAuthUI();
      window.showToast('Your session expired. Please sign in with X again.');
    } else if (!res.ok) {
      window.showToast('Vote could not be saved. Please try again later.');
    } else {
      const d = await res.json();
      votesState.totals[id] = d.totals;
      votesState.mine[id] = d.mine;
      window.showToast(`You voted for ${winner.toUpperCase()}! 🏆`);
    }
  } catch (err) {
    console.warn('Vote failed', err);
    window.showToast('Vote could not be saved. Please try again later.');
  } finally {
    setVoteButtonsDisabled(id, false);
    updateGridVoteUI(id);
    if (String(window.currentBattleId) === id) window.updateModalVoteUI();
  }
};

function setVoteButtonsDisabled(id, disabled) {
  const ids = [`grok-btn-${id}`, `human-btn-${id}`];
  if (String(window.currentBattleId) === String(id)) ids.push('modal-grok-btn', 'modal-human-btn');
  ids.forEach(elId => {
    const el = document.getElementById(elId);
    if (el) el.disabled = disabled;
  });
}

window.voteFromModal = function(event, winner) {
  if (window.currentBattleId) vote(event, winner, window.currentBattleId);
};

// ====================== DOM CONTENT LOADED ======================
document.addEventListener('DOMContentLoaded', async () => {
  setRandomBackground();
  await loadLayout();                    // header + footer (already async)
  await loadAuth();                      // who is signed in (renders the header button)
  handleLoginReturn();

  // ── NEW: Automatic page init based on <body data-page="..."> ──
  // This is the single source of truth for ALL pages
  const pageType = document.body.getAttribute('data-page');
  if (pageType) {
    await window.initPage(pageType);     // loads JSON + renders grid + deep-link
    console.log(`✅ Auto-initialized ${pageType} page (modals + grids now live)`);
  }
});
// End of common.js